@@ -11,16 +11,30 @@ final class StockView

     public function __construct(private StockRepository $stock) {}

-    public function line(string $sku): string
-    {
-        return '';
+    public function line(string $sku): string
+    {
+        $item = $this->stock->find($sku);
+
+        if ($item === null) {
+            return 'нет данных';
+        }
+
+        $left = $item['quantity'];
+
+        if (empty($left)) {
+            return 'нет данных';
+        }
+
+        return sprintf('%s: %d шт.', $item['name'], $left);
     }

     public function isLow(string $sku): bool
     {
         return ($this->stock->find($sku)['quantity'] ?? 0) < self::LOW;
     }
 }
